import posixpath as path

class strings:
    @staticmethod
    def join(sep, items):
        return sep.join(items)

print(path.join('a', 'b', 'c.txt'))
print(strings.join('-', ['x', 'y', 'z']))

class Pipeline:
        def __init__(self, data):
            self.data = data
        def where(self, pred):
            return Pipeline([x for x in self.data if pred(x)])
        def map(self, func):
            return Pipeline([func(x) for x in self.data])
        def sum(self):
            return sum(self.data)
        def len(self):
            return len(self.data)

    data = [3, 8, 1, 12, 5, 9]
    p = Pipeline(data)
    filtered = p.where(lambda x: x > 5)
    print(filtered.len())
    print(filtered.sum())
    print(filtered.map(lambda x: x * 2).sum())

